def constant_time_equals(a, b):
    if len(a) != len(b):
        return False
    r = 0
    for x, y in zip(a, b):
        r |= x ^ y
    return r == 0

def is_strong_password(pw):
    return (len(pw) >= 12 and any(c.islower() for c in pw)
            and any(c.isupper() for c in pw) and any(c.isdigit() for c in pw)
            and any(not c.isalnum() for c in pw))
